#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    size_t n, m, a, b;
    unsigned long long g0, x, y, z;
    if (!(cin >> n >> m >> a >> b >> g0 >> x >> y >> z)) return 0;

    vector<vector<unsigned long long>> hs(n, vector<unsigned long long>(m));
    unsigned long long g = g0;
    for (size_t i = 0; i < n * m; i++) {
        size_t r = i / m;
        size_t c = i % m;
        hs[r][c] = g;
        g = (g * x + y) % z;
    }

    vector<vector<unsigned long long>> min_table;

    for (size_t i = 0; i < n; i++) {
        deque<pair<size_t, size_t>> q;
        vector<unsigned long long> row_mins;
        for (size_t j = 0; j < m; j++) {
            unsigned long long h = hs[i][j];

            while (!q.empty()) {
                auto [xidx, yidx] = q.back();
                if (h <= hs[xidx][yidx]) {
                    q.pop_back();
                } else {
                    break;
                }
            }
            q.emplace_back(i, j);

            if (j + 1 < b) continue;
            if (j + 1 > b) {
                auto [_, yidx] = q.front();
                if (yidx == j - b + 1) q.pop_front();
            }

            auto [xidx, yidx] = q.front();
            row_mins.push_back(hs[xidx][yidx]);
        }
        min_table.push_back(move(row_mins));
    }

    unsigned long long ans = 0;
    for (size_t j = 0; j + b <= m; j++) {
        deque<pair<size_t, size_t>> q;
        for (size_t i = 0; i < n; i++) {
            unsigned long long h = min_table[i][j];

            while (!q.empty()) {
                auto [xidx, yidx] = q.back();
                if (h <= min_table[xidx][yidx]) {
                    q.pop_back();
                } else {
                    break;
                }
            }
            q.emplace_back(i, j);

            if (i + 1 < a) continue;
            if (i + 1 > a) {
                auto [xidx, _] = q.front();
                if (xidx == i - a + 1) q.pop_front();
            }

            auto [xidx, yidx] = q.front();
            ans += min_table[xidx][yidx];
        }
    }

    cout << ans << '\n';
    return 0;
}

